HL7 FHIR Integration Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(hl7_fhir_integration_container, "HL7 FHIR Integration Container") {
    Component(Inbound_FHIR_Router, "Inbound FHIR Router", "Apache Camel", "Parses and forwards incoming payloads using Camel Direct Endpoints.")
    Component(Data_Mapper, "Data Mapper", "Apache Camel", "Transforms and formats payloads between external formats and FHIR resources.")
    Component(FHIR_Validation_Compliance_Engine, "FHIR Validation & Compliance Engine", "Apache Camel & HAPI FHIR", "Evaluates resource integrity and checks adherence to clinical compliance standards.")
    Component(Outbound_Dispatcher, "Outbound Dispatcher", "Apache Camel", "Queues validated payloads via Camel SEDA Queues for delivery.")
}

Rel(Inbound_FHIR_Router, Data_Mapper, "Parses and forwards incoming payloads", "Camel Direct Endpoints")
Rel(Data_Mapper, FHIR_Validation_Compliance_Engine, "Evaluates resource integrity", "Camel Direct Endpoints")
Rel(FHIR_Validation_Compliance_Engine, Outbound_Dispatcher, "Queues validated payloads", "Camel SEDA Queues")

@enduml

PostgreSQL Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the PostgreSQL Database container

Container_Boundary(postgresql_database, "PostgreSQL Database") {
    Component(Patroni_Cluster_Manager, "Patroni Cluster Manager", "Patroni", "Manages the active-active high availability (99.99%) of the PostgreSQL nodes.")
    Component(PostgreSQL_Engine, "PostgreSQL Engine", "PostgreSQL with pgAudit", "Handles data persistence and strict compliance auditing for patient and clinical records.")
}

Rel(Patroni_Cluster_Manager, PostgreSQL_Engine, "Orchestrates and monitors")

@enduml

Redis Cache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(Scheduling_Microservice, "Scheduling Microservice", "External microservice that interacts with the cache layer.")

Container_Boundary(Redis_Cache, "Redis Cache") {
    Component(Redis_Cluster_Manager, "Redis Cluster Manager", "Redis Enterprise", "Manages distributed clustering, high availability, and failover for caching layers.")
    Component(Data_Structures_Engine, "Data Structures Engine", "Hashes, Sorted Sets", "Stores and retrieves structured session and scheduling cache data efficiently.")
    Component(L1_In_Memory_Cache_Wrapper, "L1 In-Memory Cache Wrapper", "In-memory wrapper", "Provides ultra-low latency local application caching alongside Redis Enterprise.")
}

Rel(Scheduling_Microservice, Redis_Cluster_Manager, "Sends RESP3 over TLS, TCP requests for caching and distributed locking", "RESP3 over TLS, TCP")
Rel(Redis_Cluster_Manager, Data_Structures_Engine, "Persists and queries hashes and sorted sets", "")
Rel(Data_Structures_Engine, L1_In_Memory_Cache_Wrapper, "Synchronizes local in-memory cache wrapper data", "")

@enduml
